-- 1. Adicionar coluna locale com default pt-BR e CHECK constraint
ALTER TABLE public.legal_documents
  ADD COLUMN locale TEXT NOT NULL DEFAULT 'pt-BR'
  CHECK (locale IN ('pt-BR', 'en'));

-- 2. Substituir UNIQUE (doc_type, version) por UNIQUE (doc_type, locale, version)
ALTER TABLE public.legal_documents
  DROP CONSTRAINT legal_documents_doc_type_version_key;

ALTER TABLE public.legal_documents
  ADD CONSTRAINT legal_documents_doc_type_locale_version_key
  UNIQUE (doc_type, locale, version);

-- 3. Substituir índice por composto incluindo locale
DROP INDEX IF EXISTS idx_legal_documents_type_version;
CREATE INDEX idx_legal_documents_type_locale_version
  ON public.legal_documents (doc_type, locale, version DESC);

